123	  let start = from;
124	  for (let i = from; i < to; i++) {
125	    const c = src[i];
126	    if (c === '"' || c === "'" || c === '`') {
127	      for (i++; i < to; i++) {
128	        if (src[i] === '\\') i++;
129	        else if (src[i] === c) break;
130	      }
131	      continue;
132	    }
133	    if (CLOSERS[c]) {
