3	// Converted from the leaflet prose: every Leaflet asset loaded from a CDN — the
4	// core bundle AND every plugin — must be version-pinned and carry an SRI hash
5	// with `crossorigin`. The trap the prose names is a partial job: the core
6	// `leaflet@1.9.4` script gets the full treatment and a plugin's `<script>` is
7	// left bare, so one un-hashed third-party URL still executes with the page's
8	// full authority. That is a static signature in the HTML, so it converts.
9	//
10	// PARSED, NOT GREPPED (the skill's rule): grep for `unpkg.com` or `integrity`
11	// answers the wrong question. The rule is about one *tag* — a `<script>`/`<link>`
12	// whose own URL is a remote Leaflet asset — so the scan reads each tag's own
13	// attributes and judges only those. A locally vendored `js/leaflet.js`, a
14	// preconnect to the CDN host, and a Leaflet URL sitting in ordinary page text are
15	// all none of this rule's business. HTML comments are stripped first, so an
16	// example of the bad wiring written in a comment never fires it.
17	
18	const HTML = /\.html?$/i;
19	const TAG = /<(script|link)\b([^>]*)>/gi;
20	const REMOTE = /^(?:https?:)?\/\//i;
21	const LEAFLET = /leaflet/i;
22	// An exact pin is a `major.minor…` version reached by the URL's own delimiters —
23	// `leaflet@1.9.4/…` (unpkg/jsdelivr), `/leaflet/1.9.4/…` (cdnjs), `leaflet-1.9.4.js`
24	// (a self-hosted mirror). A bare `@latest`, a major-only `@1`, or a version-less
25	// path matches none of them.
26	const PINNED = /[@/-]\d+\.\d+[\w.+-]*(?:$|[/?#])/;
27	const SRI = /^sha(?:256|384|512)-\S+/;
28	
29	// `source` with its HTML comments blanked out, newlines kept so line numbers
30	// don't shift.
31	function stripHtmlComments(source) {
32	  return source.replace(/<!--[\s\S]*?-->/g, (m) => m.replace(/[^\n]/g, ' '));
33	}
34	
35	// The tag's own attributes as a lowercased-name map. A valueless attribute
36	// (`crossorigin`) maps to '' — present, which is what the rule asks.
37	function attributes(text) {
38	  const attrs = {};
39	  const re = /([a-zA-Z_:][-\w:.]*)(?:\s*=\s*("[^"]*"|'[^']*'|[^\s"'>]+))?/g;
40	  for (let m = re.exec(text); m; m = re.exec(text)) {
41	    const raw = m[2] ?? '';
42	    attrs[m[1].toLowerCase()] =
43	      raw.startsWith('"') || raw.startsWith("'") ? raw.slice(1, -1) : raw;
44	  }
45	  return attrs;
46	}
47	
48	const rule = {
49	  id: 'leaflet/asset-integrity',
50	  severity: 'blocking',
51	  description:
52	    'Every CDN-loaded Leaflet asset — core bundle and plugins alike — is version-pinned and carries an SRI hash with crossorigin',
53	  doc: 'packs/leaflet/RULES.md',
54	  why: 'an un-pinned or un-hashed third-party script runs with the page\'s full authority, so whatever the CDN serves tomorrow is what your users execute — and the hole is usually a plugin tag left bare beside a correctly wired core bundle',
55	
56	  run(ctx) {
57	    const out = [];
58	    for (const file of ctx.files) {
59	      if (!HTML.test(file)) continue;
60	      const raw = ctx.read(file);
61	      if (raw === null || !LEAFLET.test(raw)) continue;
62	      const src = stripHtmlComments(raw);
63	      TAG.lastIndex = 0;
64	      for (let m = TAG.exec(src); m; m = TAG.exec(src)) {
65	        const attrs = attributes(m[2]);
66	        const url = m[1].toLowerCase() === 'script' ? attrs.src : attrs.href;
67	        if (!url || !REMOTE.test(url) || !LEAFLET.test(url)) continue;
68	
69	        const missing = [];
70	        if (!PINNED.test(url)) missing.push('an exact version pin (leaflet@1.9.4, never @latest)');
71	        if (!SRI.test(attrs.integrity ?? '')) missing.push('integrity="sha256-…"');
72	        if (attrs.crossorigin === undefined) missing.push('crossorigin');
73	        if (missing.length === 0) continue;
74	
75	        out.push(finding(rule, {
76	          file,
77	          line: src.slice(0, m.index).split('\n').length,
78	          what: `loads the Leaflet asset ${url} without ${missing.join(' / ')}`,
79	          fix: `pin the exact version in the URL and carry integrity="sha256-…" + crossorigin="" on this <${m[1].toLowerCase()}> — the plugin tags too, not just the core bundle`,
80	        }));
81	      }
82	    }
83	    return out;
84	  },
85	};
86	
87	export default rule;
