8	// The distribution names under [project.optional-dependencies] in a
9	// pyproject.toml's text. Line-based (the engine carries no TOML parser): find
10	// the section header, and until the next top-level [header] collect the leading
11	// package token of every quoted requirement string. Inside that section every
12	// quoted token is a requirement (the extra-group keys — `yamnet = [ ... ]` —
13	// are unquoted), so this needs no value/key discrimination. Handles the
14	// standard table form (grounded in missingbulb/LaughCounter). The rarer inline
15	// form — `optional-dependencies = { extra = [...] }` under [project] — is not
16	// parsed: a safe false-negative (nothing flagged), never a false-positive.
17	export function optionalDistNames(tomlText) {
18	  const names = new Set();
19	  let inSection = false;
20	  for (const raw of tomlText.split('\n')) {
21	    const header = /^\s*\[([^\]]+)\]/.exec(raw);
22	    if (header) { inSection = header[1].trim() === 'project.optional-dependencies'; continue; }
