49	const CONFIG_PATH = '.github/site.config';
50	
51	// The five required keys, plus the one optional key. `allowEmpty` marks the
52	// values whose empty form is a real, stated answer ("no build" / "no tests")
53	// rather than an omission; `optional` marks the key a config may leave out
54	// entirely (see the header for why exactly one key gets that licence).
55	export const KEYS = [
56	  { name: 'publish_root', allowEmpty: false },
57	  { name: 'publish_paths', allowEmpty: false },
58	  { name: 'version_files', allowEmpty: false },
59	  { name: 'build_command', allowEmpty: true },
60	  { name: 'test_command', allowEmpty: true },
61	  { name: 'build_vars', allowEmpty: true, optional: true },
62	];
63	
64	// A build_vars entry becomes an environment variable name, so it must be one.
