67	const ENV_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;
68	
69	// dotenv-ish: KEY=value, one per line; # comments and blank lines ignored; the
70	// value may be wrapped in matching single or double quotes (so a command with
71	// trailing spaces or a leading # is expressible). Returns { values, errors }.
72	export function parseConfig(text) {
73	  const values = new Map();
74	  const errors = [];
75	  const known = new Set(KEYS.map((k) => k.name));
76	
77	  text.split('\n').forEach((raw, i) => {
78	    const line = raw.trim();
79	    if (!line || line.startsWith('#')) return;
80	    const eq = line.indexOf('=');
81	    if (eq < 1) {
82	      errors.push(`${CONFIG_PATH}:${i + 1}: '${line}' is not KEY=value`);
83	      return;
84	    }
85	    const key = line.slice(0, eq).trim();
86	    let value = line.slice(eq + 1).trim();
87	    if (value.length >= 2 && (value[0] === '"' || value[0] === "'") && value.at(-1) === value[0]) {
88	      value = value.slice(1, -1);
89	    }
90	    if (!known.has(key)) {
91	      errors.push(`${CONFIG_PATH}:${i + 1}: unknown key '${key}' — the keys are ${[...known].join(', ')}`);
92	      return;
93	    }
94	    if (values.has(key)) errors.push(`${CONFIG_PATH}:${i + 1}: '${key}' is set twice`);
95	    values.set(key, value);
96	  });
97	
98	  for (const { name, allowEmpty, optional } of KEYS) {
99	    if (!values.has(name)) {
100	      if (!optional) errors.push(`${CONFIG_PATH}: required key '${name}' is missing`);
101	    } else if (!allowEmpty && !values.get(name)) {
102	      errors.push(`${CONFIG_PATH}: '${name}' is empty — it must name a real path`);
103	    }
104	  }
105	
106	  for (const name of (values.get('build_vars') ?? '').split(/\s+/).filter(Boolean)) {
107	    if (!ENV_NAME.test(name)) {
108	      errors.push(`${CONFIG_PATH}: build_vars entry '${name}' is not a variable name — list the repo variable NAMES to export, space-separated, never their values`);
109	    }
110	  }
111	  return { values, errors };
112	}
113	
114	if (process.argv[1] === fileURLToPath(import.meta.url)) {
115	  let text;
116	  try {
117	    text = readFileSync(CONFIG_PATH, 'utf8');
118	  } catch {
119	    console.error(`read-site-config: ${CONFIG_PATH} is missing — every static-site repo declares its publish set explicitly.`);
120	    process.exit(1);
121	  }
122	
123	  const { values, errors } = parseConfig(text);
124	  if (errors.length) {
125	    for (const e of errors) console.error(`read-site-config: ${e}`);
126	    process.exit(1);
127	  }
128	
129	  // An omitted optional key emits as empty, so every consumer of these outputs
130	  // sees the same "" it would see from an explicitly empty value.
131	  const out = KEYS.map(({ name }) => `${name}=${values.get(name) ?? ''}`).join('\n');
132	  if (process.env.GITHUB_OUTPUT) appendFileSync(process.env.GITHUB_OUTPUT, `${out}\n`);
133	  console.log(out);
