41	          what: `the newly declared "${packId}" pack asks "${q.id}" but its entry records no answer`,
42	          fix: `interview the owner and record it on the "${packId}" entry as "answers": { "${q.id}": "<answer>" } ("n/a — none wanted" is a valid answer) — ${q.distill}`,
