import re, os

hits = []
for base in ['packs', '.claudinite/local/packs']:
    for root, dirs, files in os.walk(base):
        for f in files:
            if f.endswith('.mjs') and '/test/' not in root+'/' and not f.endswith('.test.mjs'):
                path = os.path.join(root, f).replace('./','')
                text = open(path, encoding='utf-8').read()
                for m in re.finditer(r"\bdoc:\s*(['\"])(.*?)\1", text):
                    hits.append((path, m.group(2)))

pack_re = re.compile(r'^(\.claudinite/local/packs/[^/]+|packs/[^/]+)/')

bad = []
for path, docval in hits:
    if docval.startswith('http'):
        continue
    root_ok = os.path.isfile(docval)
    m = pack_re.match(path)
    pack_ok = False
    if m:
        pack_ok = os.path.isfile(os.path.join(m.group(1), docval))
    if not (root_ok or pack_ok):
        bad.append((path, docval, root_ok, pack_ok))

print(f"total hits: {len(hits)}")
print(f"unresolved under either interpretation: {len(bad)}")
for b in bad:
    print(b)
EOF

