1	import { finding } from '../../../../../engine/checks/helpers/findings.mjs';
2	import { VERSION_SOURCE, versionFromLiteral, compareVersions, versionsEqual, nextVersion } from '../../../../../engine/version.mjs';
3	
4	// A PACK'S CONTENT IS DELIVERED ON ITS VERSION NUMBER, and on nothing else. The
5	// engine tree vendors wholesale on every converge; a pack's directory ships only
6	// where `planPackUpdates` sees `installed.packVersions[id] < pack.version`
7	// (updates/pack-update.mjs). So a canon commit that edits `packs/<id>/` without
8	// touching that number lands here, goes green here, and reaches no member — the
9	// fleet keeps the old bytes while canon believes the change shipped.
10	//
11	// #939 is what that costs. A check vocabulary rename updated the engine and the
12	// canon's own packs in one commit: the engine, delivered unconditionally, reached
13	// every member and rejected the old spelling; the pack carrying the new spelling
14	// stayed at `version: 1` and reached nobody. The mixed tree failed each member's
15	// self-test, the update PR parked, and the fix could not arrive by the route that
16	// delivers fixes. Seven repos sat frozen for five days.
17	//
18	// So the invariant this rule holds is one line: A CHANGE UNDER `packs/<id>/` IS A
19	// CHANGE TO THAT PACK'S VERSION. Every SHIPPING byte counts, because every one of
20	// them rides the same directory copy — prose, a skill, a check module, a migration
21	// record. A pack's tests sit beside the files they cover and are the one thing in
22	// that directory no vendor set carries (compute-vendor-set drops `*.test.mjs`), so
23	// nobody is waiting on them and a bump for one would re-deliver every pack in the
24	// tree to say nothing.
25	// It is the pack-side twin of `engine-release-record` (the claudinite local pack),
26	// which holds the same line for `ENGINE_VERSION`.
27	//
28	// WORK SCOPE: the question is what THIS change did. The tree always contains a
29	// version number; only the diff says whether it moved with the content beside it.
30	const LOCAL_PACKS = '.claudinite/local/packs';
31	
32	// Each pack's version-bump log, next to its manifest — see `versionRecorded`
33	// below for what it must carry once a bump lands.
34	export const VERSIONS_FILENAME = 'VERSIONS.md';
35	
36	// The pack ids a changed-file list touches, in first-seen order. Anchored at
37	// `packs/<id>/` so the canon's own local packs (which vendor nowhere, carry no
38	// version and reach no member) and the tree's own files (`packs/README.md`,
39	// `packs/directory.GENERATED.md`) are outside it by construction. Tests drop out for
40	// the same reason the local packs do: nothing delivers them. `VERSIONS.md` drops
41	// out too — it is the log OF bumps, not content a bump ships, so editing it alone
42	// (recording a bump made elsewhere in the same change, or a wording fix to an old
43	// row) must never itself demand another bump.
44	export function packsTouched(changed) {
45	  const ids = [];
46	  for (const file of changed ?? []) {
47	    if (file.startsWith(`${LOCAL_PACKS}/`) || file.endsWith('.test.mjs') || file.endsWith(`/${VERSIONS_FILENAME}`)) continue;
48	    const m = /^packs\/([^/]+)\//.exec(file);
49	    if (m && !ids.includes(m[1])) ids.push(m[1]);
50	  }
51	  return ids;
52	}
53	
54	// The `version:` a pack manifest declares, or null when it declares none (a
55	// manifest that is absent on one side of the diff, or one the schema check owns).
56	// The preceding-character class is what keeps `minEngineVersion:` out of it.
57	const PACK_VERSION_RE = new RegExp(String.raw`(?:^|[\s{,])version:\s*'?(${VERSION_SOURCE})'?`, 'm');
58	export function declaredPackVersion(text) {
59	  const m = PACK_VERSION_RE.exec(text ?? '');
60	  return m ? versionFromLiteral(m[1]) : null;
61	}
62	
63	// Does the pack's VERSIONS.md carry a row for this version? A row is a table row
64	// whose first cell is the bare version — the same shape `engine/RELEASES.md`
65	// rows use, so the log reads as a table a human maintains, not a format this
66	// check invented. No run link is required here (unlike an engine release): a
67	// pack bump has no canary rehearsal to cite, so the row's own prose is the
68	// record.
69	const ROW_VERSION_RE = new RegExp(String.raw`^\|\s*(${VERSION_SOURCE})\s*\|`);
70	export function versionRecorded(text, version) {
71	  for (const line of (text ?? '').split('\n')) {
72	    const m = ROW_VERSION_RE.exec(line.trim());
73	    if (m && versionsEqual(versionFromLiteral(m[1]), version)) return true;
74	  }
75	  return false;
76	}
77	
78	const rule = {
79	  id: 'pack-version-bumped',
80	  severity: 'blocking',
81	  scope: 'work',
82	  description: 'A change under packs/<id>/ bumps that pack\'s version, and a bump lands with its VERSIONS.md row',
83	  doc: 'docs/versioned-updates/DESIGN.md',
84	  why: 'a member receives a pack directory only when the canon\'s version exceeds the one it has installed, so content edited without a bump reaches nobody while canon CI reports it shipped (#939 froze seven repos for five days that way); an unrecorded bump is the same evidence gap on a smaller scale — "what did version N change?" becomes unanswerable once the commit scrolls out of history',
85	
86	  run(work) {
87	    const findings = [];
88	    for (const id of packsTouched(work.changedFiles)) {
89	      const manifest = `packs/${id}/pack.mjs`;
90	      const head = declaredPackVersion(work.read(manifest));
91	      if (head === null) continue;                     // the pack was deleted, or declares no version — other rules own that
92	      const base = declaredPackVersion(work.readBase(manifest));
93	      if (base === null) continue;                     // a pack this change introduces: its first version ships to everyone
94	      const moved = compareVersions(head, base);
95	
96	      if (moved <= 0) {
97	        findings.push(finding(rule, {
98	          file: manifest,
99	          what: moved === 0
100	            ? `this change edits packs/${id}/ but leaves its version at ${head}`
101	            : `packs/${id}/ moves its version backwards, ${base} → ${head}`,
102	          fix: moved === 0
103	            ? `raise \`version\` in ${manifest} to '${nextVersion(base)}' — the version is the whole delivery signal, so an edit `
104	              + 'that does not move it stays in the canon forever'
105	            : 'pack versions only ever increase — the update flow reads them as an ordering, so a lowered number tells '
106	              + 'every member it is already up to date',
107	        }));
108	        continue;
109	      }
110	
111	      const versionsFile = `packs/${id}/${VERSIONS_FILENAME}`;
112	      if (!versionRecorded(work.read(versionsFile), head)) {
113	        findings.push(finding(rule, {
114	          file: versionsFile,
115	          what: `packs/${id}/ bumps its version to ${head}, and ${versionsFile} carries no row for it`,
116	          fix: `add a row to ${versionsFile} for version ${head} saying what changed`,
117	        }));
118	      }
119	    }
120	    return findings;
121	  },
122	};
123	
124	export default rule;
125

