1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { readFileSync, existsSync } from 'node:fs';
4	import { join, dirname } from 'node:path';
5	import { fileURLToPath } from 'node:url';
6	import { discoverPacks } from '../engine/pack_loader/pack-registry.mjs';
7	import { ruleBlocks, readmeRuleIndex, SEVERITIES, REASONS } from './rule-index.mjs';
8	
9	// A pack README's rule index states each prose rule's word count, the severity
10	// of ignoring it and the reason it exists. The word count is derived from
11	// RULES.md, and RULES.md is appended to several times a week — so it is held
12	// against the prose here rather than trusted to stay current on its own.
13	const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
14	
15	const packsWithProse = async () => {
16	  const { packs } = await discoverPacks({ localRoot: ROOT });
17	  return packs.filter((p) => !p.local && p.prose && existsSync(join(ROOT, 'packs', p.id, 'README.md')));
18	};
19	
20	test('each pack README indexes its RULES.md rules, in order, with their word counts', async () => {
21	  for (const pack of await packsWithProse()) {
22	    const rules = ruleBlocks(readFileSync(join(ROOT, 'packs', pack.id, pack.prose), 'utf8'));
23	    if (!rules.length) continue;
24	    const rows = readmeRuleIndex(readFileSync(join(ROOT, 'packs', pack.id, 'README.md'), 'utf8'));
25	
26	    assert.equal(
27	      rows.length, rules.length,
28	      `packs/${pack.id}/README.md indexes ${rows.length} rules; ${pack.prose} carries ${rules.length}. Add a row for every rule, in the order the prose lists them.`
29	    );
30	    rules.forEach((rule, i) => {
31	      assert.equal(
32	        rows[i].words, rule.words,
33	        `packs/${pack.id}/README.md row ${i + 1} ("${rows[i].label}") says ${rows[i].words} words; "${rule.leadIn}" is ${rule.words}. Recount the row in the same change that edits the rule.`
34	      );
35	    });
36	  }
37	});
38	
39	test('each pack README lists every check it runs, with a severity and a reason', async () => {
40	  const { packs } = await discoverPacks({ localRoot: ROOT });
41	  for (const pack of packs.filter((p) => !p.local)) {
42	    const checks = [...(pack.worldRules ?? []), ...(pack.workRules ?? []), ...(pack.skillChecks ?? [])];
43	    if (!checks.length) continue;
44	    const readme = join(ROOT, 'packs', pack.id, 'README.md');
45	    assert.ok(existsSync(readme), `packs/${pack.id} runs ${checks.length} checks and has no README to index them.`);
46	    const rows = checkRows(readFileSync(readme, 'utf8'));
47	    for (const check of checks) {
48	      const row = rows.get(check.id);
49	      assert.ok(row, `packs/${pack.id}/README.md does not list the \`${check.id}\` check. Add a row for it in the checks table.`);
50	      assert.ok(
51	        SEVERITIES.includes(row.severity),
52	        `packs/${pack.id}/README.md gives \`${check.id}\` severity "${row.severity}"; use one of ${SEVERITIES.join(', ')}.`
53	      );
54	      assert.ok(
55	        REASONS.includes(row.reason),
56	        `packs/${pack.id}/README.md gives \`${check.id}\` reason "${row.reason}"; use one of ${REASONS.join(', ')}.`
57	      );
58	    }
59	  }
60	});
61	
62	// A checks table's rows are keyed by the check id in their first cell, and read
63	// `| Check | Severity | Reason | Enforcement |`.
64	function checkRows(readme) {
65	  const rows = new Map();
66	  for (const line of readme.split('\n')) {
67	    if (!line.startsWith('| `')) continue;
68	    const cells = line.split('|').slice(1, -1).map((c) => c.trim());
69	    const id = /^`([^`]+)`$/.exec(cells[0]);
70	    if (id && cells.length === 4) rows.set(id[1], { severity: cells[1], reason: cells[2] });
71	  }
72	  return rows;
73	}
