76	  for (const pack of await packsWithProse()) {
77	    for (const row of readmeRuleIndex(readFileSync(join(ROOT, 'packs', pack.id, 'README.md'), 'utf8'))) {
78	      assert.ok(
79	        SEVERITIES.includes(row.severity),
80	        `packs/${pack.id}/README.md row "${row.label}" has severity "${row.severity}"; use one of ${SEVERITIES.join(', ')}.`
81	      );
82	      assert.ok(
